// ============================================================================
// SECTION 1: Parse correctness properties
// ============================================================================

// propParseValidJSON asserts that Parse does NOT return an error for any
// structurally valid JSON generated by our generators.
func TestProperty_ParseValidJSON(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := genJSONWithoutComments.Draw(t, "jsonInput")
		doc, err := Parse([]byte(input))
		if err != nil {
			t.Fatalf("Parse error for valid JSON %q: %v", input, err)
		}
		if doc == nil {
			t.Fatal("Parse returned nil Document with no error")
			return
		}
		if doc.Kind != KindDocument {
			t.Fatalf("Expected KindDocument, got %s", doc.Kind)
		}
	})
}

// propParseValidJSONC asserts Parse succeeds for JSONC with comments.
func TestProperty_ParseValidJSONC(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := genFullJSONC(t)
		doc, err := Parse([]byte(input))
		if err != nil {
			t.Fatalf("Parse error for JSONC %q: %v", input, err)
		}
		if doc == nil {
			t.Fatal("Parse returned nil Document")
		}
	})
}

// propParseNumberValues asserts numbers parse correctly and the raw text matches.
func TestProperty_ParseNumberValues(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := genNumbersString.Draw(t, "num")
		if input == "" {
			return
		}
		// Wrap in an array to test as a value
		src := "[" + input + "]"
		doc, err := Parse([]byte(src))
		if err != nil {
			t.Fatalf("Parse error for number %q: %v", input, err)
		}
		arr := doc.FirstChild()
		if arr == nil || arr.Kind != KindArray {
			t.Fatalf("Expected array, got %v", arr)
		}
		// The number node should be the first value element
		for _, c := range arr.Children {
			if c.IsValue() {
				if c.Kind != KindNumber {
					t.Fatalf("Expected Number node, got %s for value %q", c.Kind, c.Value)
				}
				// Verify it parses as a valid JSON number
				var f float64
				if err := json.Unmarshal([]byte(c.Value), &f); err != nil {
					continue
				}
				if math.IsInf(f, 0) || math.IsNaN(f) {
					t.Fatalf("Number %q produced Inf/NaN", c.Value)
				}
				return
			}
		}
		t.Fatalf("No value node found for number %q", input)
	})
}

// propParseStringValues asserts strings parse correctly with proper content.
func TestProperty_ParseStringValues(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		s := genJSONString.Draw(t, "str")
		src := "[" + s + "]"
		doc, err := Parse([]byte(src))
		if err != nil {
			t.Fatalf("Parse error for string %q: %v", s, err)
		}
		arr := doc.FirstChild()
		if arr == nil || arr.Kind != KindArray {
			t.Fatalf("Expected array root, got %v", arr)
		}
		found := false
		for _, c := range arr.Children {
			if c.Kind == KindString {
				found = true
				// The raw text should include the surrounding quotes
				if !strings.HasPrefix(c.Value, "\"") || !strings.HasSuffix(c.Value, "\"") {
					t.Fatalf("String value %q should have surrounding quotes", c.Value)
				}
				break
			}
		}
		if !found {
			t.Fatalf("No String node found for %q", s)
		}
	})
}

// propParseBooleanValues asserts true/false are correctly identified.
func TestProperty_ParseBooleanValues(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := rapid.SampledFrom([]string{"true", "false", " null ", " true ", "false "}).Draw(t, "boolInput")
		doc, err := Parse([]byte(input))
		if err != nil {
			t.Fatalf("Parse error for %q: %v", input, err)
		}
		// Should at least find some boolean nodes or the value
		bools := doc.FindAll(KindBoolean)
		if strings.Contains(input, "true") || strings.Contains(input, "false") {
			if len(bools) == 0 && !strings.Contains(input, "null") {
				t.Fatalf("No Boolean node found for %q", input)
			}
		}
	})
}

// propParseNull asserts null is correctly identified.
func TestProperty_ParseNull(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		// Must wrap in array for proper parsing since null alone is valid JSON
		input := rapid.SampledFrom([]string{
			"[null]",
			"[ null ]",
			"[null, null]",
			"{\"a\": null}",
		}).Draw(t, "nullInput")

		doc, err := Parse([]byte(input))
		if err != nil {
			t.Fatalf("Parse error for %q: %v", input, err)
		}
		nulls := doc.FindAll(KindNull)
		if len(nulls) == 0 {
			t.Fatalf("No Null nodes found for %q", input)
		}
		for _, n := range nulls {
			if n.Value != "null" {
				t.Fatalf("Null node has value %q, expected %q", n.Value, "null")
			}
		}
	})
}

