// propParseObjectStructure verifies object parsing preserves member structure.
func TestProperty_ParseObjectStructure(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := genObject(t)
		doc, err := Parse([]byte(input))
		if err != nil {
			t.Fatalf("Parse error for object %q: %v", input, err)
		}
		obj := doc.FirstChild()
		if obj == nil {
			t.Fatalf("No children in document for %q", input)
			return
		}
		if obj.Kind != KindObject {
			t.Fatalf("Expected Object, got %s", obj.Kind)
		}

		// Verify brace positions
		hasLBrace, hasRBrace := false, false
		for _, c := range obj.Children {
			if c.Kind == KindLBrace {
				hasLBrace = true
			}
			if c.Kind == KindRBrace {
				hasRBrace = true
			}
		}
		if !hasLBrace {
			t.Fatal("Object missing { brace node")
		}
		if !hasRBrace {
			t.Fatal("Object missing } brace node")
		}

		// Verify members have keys and values
		for _, m := range obj.Members() {
			key := m.KeyNode()
			val := m.ValueNode()
			if key == nil {
				t.Fatal("Member without key node")
				return
			}
			if val == nil {
				t.Fatal("Member without value node")
			}
			if !strings.HasPrefix(key.Value, `"`) {
				t.Fatalf("Key node value %q should be quoted", key.Value)
			}
		}
	})
}

