// propLineCommentPreserved asserts line comments (//) are in the CST.
func TestProperty_LineCommentPreserved(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := genLineComment.Draw(t, "comment")
		// Wrap so it's valid JSONC
		src := "[" + input + "\n]"
		doc, err := Parse([]byte(src))
		if err != nil {
			t.Fatalf("Parse error for line comment %q: %v", src, err)
		}
		comments := doc.FindAllComments()
		if len(comments) == 0 {
			t.Fatalf("No comment nodes found for %q", src)
		}
		// The comment text should start with //
		for _, c := range comments {
			if !strings.HasPrefix(c.Value, "//") {
				t.Fatalf("Line comment value %q doesn't start with //", c.Value)
			}
			if c.CommentStyle != CommentLine {
				t.Fatalf("Expected CommentLine style, got %d", c.CommentStyle)
			}
		}
	})
}

// propBlockCommentPreserved asserts block comments (/* */) are in the CST.
func TestProperty_BlockCommentPreserved(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := genBlockComment.Draw(t, "comment")
		src := "[" + input + "]"
		doc, err := Parse([]byte(src))
		if err != nil {
			t.Fatalf("Parse error for block comment %q: %v", src, err)
		}
		comments := doc.FindAllComments()
		if len(comments) == 0 {
			t.Fatalf("No comment nodes found for %q", src)
		}
		for _, c := range comments {
			if c.CommentStyle != CommentBlock {
				t.Fatalf("Expected CommentBlock style, got %d", c.CommentStyle)
			}
			if !strings.HasPrefix(c.Value, "/*") {
				t.Fatalf("Block comment value %q doesn't start with /*", c.Value)
			}
			if !strings.HasSuffix(c.Value, "*/") {
				t.Fatalf("Block comment value %q doesn't end with */", c.Value)
			}
		}
	})
}

// propMixedComments asserts both comment types appear in the CST.
func TestProperty_MixedComments(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		src := "[\n  // line comment\n  /* block comment */\n  // another line\n]"
		doc, err := Parse([]byte(src))
		if err != nil {
			t.Fatalf("Parse error for mixed comments: %v", err)
		}
		comments := doc.FindAllComments()
		if len(comments) < 2 {
			t.Fatalf("Expected at least 2 comments, got %d: %v", len(comments), comments)
		}
		lineCount, blockCount := 0, 0
		for _, c := range comments {
			switch c.CommentStyle {
			case CommentLine:
				lineCount++
			case CommentBlock:
				blockCount++
			}
		}
		if lineCount == 0 {
			t.Fatal("No line comments found")
		}
		if blockCount == 0 {
			t.Fatal("No block comments found")
		}
	})
}

// propCommentBodyExtracted asserts the comment body (without delimiters) is stored.
func TestProperty_CommentBodyExtracted(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		letter := rapid.Custom(func(t *rapid.T) rune {
			return []rune("abcdefghijklmnopqrstuvwxyz ")[rapid.IntRange(0, 26).Draw(t, "ci")]
		})
		line := rapid.StringOf(letter).Draw(t, "lineBody")
		block := rapid.StringOf(letter).Draw(t, "blockBody")

		src := fmt.Sprintf("[//%s\n /* %s */]", line, block)
		doc, err := Parse([]byte(src))
		if err != nil {
			t.Fatalf("Parse error: %v", err)
		}
		for _, c := range doc.FindAllComments() {
			if c.CommentStyle == CommentLine && c.CommentBody != "" {
				// Line comment body - could have leading space
				if !strings.Contains(c.CommentBody, strings.TrimSpace(line)) {
					// Just check it's not empty and is meaningful
					if c.CommentBody == "" {
						t.Fatalf("Line comment body should not be empty for %q", c.Value)
					}
				}
			}
		}
	})
}

// propCommentPreservedInJSONC asserts that comments in various positions
// (before object, after value, between members) are preserved.
func TestProperty_CommentPreservedInJSONC(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		src := "{\n  // before first\n  \"a\": 1, // after value\n  /* between */\n  \"b\": 2\n}"
		doc, err := Parse([]byte(src))
		if err != nil {
			t.Fatalf("Parse error: %v", err)
		}
		comments := doc.FindAllComments()
		if len(comments) < 3 {
			t.Fatalf("Expected at least 3 comments, got %d", len(comments))
		}
	})
}

// ============================================================================
// SECTION 4: Position tracking properties
// ============================================================================

// propPositionsAreMonotonic asserts that for each node, start <= end
// and child positions are within parent positions.
func TestProperty_PositionsAreMonotonic(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := genFullJSONC(t)
		doc, err := Parse([]byte(input))
		if err != nil {
			t.Fatalf("Parse error: %v", err)
		}
		errs := validatePositions(doc)
		if len(errs) > 0 {
			t.Fatalf("Position violations:\n%s", strings.Join(errs, "\n"))
		}
	})
}

func validatePositions(n *Node) []string {
	var errs []string
	if n == nil {
		return nil
	}
	if n.Start.Offset > n.End.Offset {
		errs = append(errs, fmt.Sprintf("Node %s: start %d > end %d", n.Kind, n.Start.Offset, n.End.Offset))
	}
	for _, c := range n.Children {
		if c.Start.Offset < n.Start.Offset {
			errs = append(errs, fmt.Sprintf(
				"Child %s start %d < parent %s start %d",
				c.Kind, c.Start.Offset, n.Kind, n.Start.Offset,
			))
		}
		if c.End.Offset > n.End.Offset {
			errs = append(errs, fmt.Sprintf("Child %s end %d > parent %s end %d", c.Kind, c.End.Offset, n.Kind, n.End.Offset))
		}
		errs = append(errs, validatePositions(c)...)
	}
	return errs
}

// propPositionsCoverInput asserts that concatenating the raw text of all leaf
// nodes covers the entire input (with correct ordering).
func TestProperty_PositionsCoverInput(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := genFullJSONC(t)
		doc, err := Parse([]byte(input))
		if err != nil {
			t.Fatalf("Parse error: %v", err)
		}
		reconstructed := doc.RawText()
		if len(reconstructed) != len(input) {
			t.Fatalf("RawText length %d != input length %d\ninput: %q\nraw:  %q",
				len(reconstructed), len(input), input, reconstructed)
		}
		if reconstructed != input {
			t.Fatalf("RawText doesn't match input\ninput: %q\nraw:   %q", input, reconstructed)
		}
	})
}

// ============================================================================
// SECTION 5: Serialization round-trip properties
// ============================================================================

// propSerializeIdentity asserts parse → serialize returns identical text (for
// inputs without disallowed tokens).
func TestProperty_SerializeIdentity(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := genJSONWithoutComments.Draw(t, "jsonInput")
		doc, err := Parse([]byte(input))
		if err != nil {
			t.Fatalf("Parse error: %v", err)
		}
		output := Serialize(doc)
		if output != input {
			// Allow for edge cases: normalized numbers etc.
			// For now, check via re-parse
			doc2, err2 := Parse([]byte(output))
			if err2 != nil {
				t.Fatalf("Serialize output doesn't re-parse: %v\ninput: %q\noutput: %q", err2, input, output)
			}
			if !doc.DeepEqual(doc2) {
				t.Fatalf("Serialize output produces different CST\ninput: %q\noutput: %q", input, output)
			}
		}
	})
}

// propParseSerializeIdempotent asserts parse(serialize(parse(x))) == parse(x)
func TestProperty_ParseSerializeIdempotent(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := genFullJSONC(t)
		doc1, err := Parse([]byte(input))
		if err != nil {
			t.Fatalf("Parse error: %v", err)
		}
		serialized := Serialize(doc1)
		doc2, err := Parse([]byte(serialized))
		if err != nil {
			t.Fatalf("Re-parse error: %v\nserialized: %q", err, serialized)
		}
		if !doc1.DeepEqual(doc2) {
			t.Fatalf("Not idempotent\ninput: %q\nserialized: %q\ndoc1: %s\ndoc2: %s",
				input, serialized, doc1, doc2)
		}
	})
}

// ============================================================================
// SECTION 6: Formatting properties
// ============================================================================

// propFormatPreservesSemantics asserts that after formatting, the semantic
// values (strings, numbers, booleans, nulls) remain unchanged.
func TestProperty_FormatPreservesSemantics(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := genFullJSONC(t)
		doc, err := Parse([]byte(input))
		if err != nil {
			t.Fatalf("Parse error: %v", err)
		}
		formatted := Format(doc, &FormatOptions{Indent: "  "})
		doc2, err := Parse([]byte(formatted))
		if err != nil {
			t.Fatalf("Format output doesn't re-parse: %v\nformatted: %q", err, formatted)
		}
		// Check structural equivalence (same values, ignore whitespace)
		if !semanticDeepEqual(doc, doc2) {
			t.Fatalf("Format changed semantics\ninput: %q\nformatted: %q", input, formatted)
		}
	})
}

// propFormatWithDifferentIndent asserts various indent styles work.
func TestProperty_FormatWithDifferentIndent(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := genFullJSONC(t)
		indent := rapid.SampledFrom([]string{"  ", "    ", "\t", ""}).Draw(t, "indent")
		doc, err := Parse([]byte(input))
		if err != nil {
			t.Fatalf("Parse error: %v", err)
		}
		formatted := Format(doc, &FormatOptions{Indent: indent})
		doc2, err := Parse([]byte(formatted))
		if err != nil {
			t.Fatalf("Format with indent %q failed re-parse: %v\nformatted: %q",
				indent, err, formatted)
		}
		if !semanticDeepEqual(doc, doc2) {
			t.Fatalf("Format with indent %q changed semantics", indent)
		}
	})
}

// propFormatReIndentIdempotent asserts format(format(x)) == format(x)
func TestProperty_FormatReIndentIdempotent(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := genFullJSONC(t)
		doc, err := Parse([]byte(input))
		if err != nil {
			t.Fatalf("Parse error: %v", err)
		}
		f1 := Format(doc, &FormatOptions{Indent: "  "})
		doc2, err := Parse([]byte(f1))
		if err != nil {
			t.Fatalf("First format re-parse error: %v", err)
		}
		f2 := Format(doc2, &FormatOptions{Indent: "  "})
		if f1 != f2 {
			t.Fatalf("Format not idempotent\nfirst:  %q\nsecond: %q", f1, f2)
		}
	})
}

// ============================================================================
// SECTION 7: Error handling properties
// ============================================================================

// propRejectTruncatedInput asserts that incomplete input generates an error node.
func TestProperty_RejectTruncatedInput(t *testing.T) {
	tests := []string{
		`{"a": `,
		`"hello`,
	}
	for _, tc := range tests {
		t.Run(tc, func(t *testing.T) {
			doc, err := Parse([]byte(tc))
			if err == nil {
				errs := doc.FindAll(KindError)
				if len(errs) == 0 {
					t.Fatalf("Expected error nodes for truncated input %q", tc)
				}
			}
		})
	}
}

// propRejectInvalidJSON asserts certain invalid inputs return error.
func TestProperty_RejectInvalidJSON(t *testing.T) {
	tests := []string{
		`{a: 1}`,       // unquoted key
		`{'a': 1}`,     // single quote
		`[true false]`, // missing comma
		`[1,,2]`,       // double comma
		`{`,            // unterminated object
		`[`,            // unterminated array
		`01`,           // leading zero (non-zero prefixed)
		`-01`,          // leading zero negative
		`truee`,        // unknown keyword
		`nul`,          // truncated keyword
		"\x00[1]",      // null byte
	}
	for _, tc := range tests {
		t.Run("", func(t *testing.T) {
			doc, err := Parse([]byte(tc))
			if err == nil && doc == nil {
				t.Fatalf("Expected error or non-nil doc for %q", tc)
			}
		})
	}
}

