// propParseEmptyArray asserts empty arrays work.
func TestProperty_ParseEmptyArray(t *testing.T) {
	doc, err := Parse([]byte("[]"))
	if err != nil {
		t.Fatalf("Parse error for empty array: %v", err)
	}
	arr := doc.FirstChild()
	if arr == nil || arr.Kind != KindArray {
		t.Fatalf("Expected Array, got %v", arr)
	}
	elements := arr.Elements()
	if len(elements) != 0 {
		t.Fatalf("Expected 0 elements, got %d", len(elements))
	}
}

// propParseEmptyObject asserts empty objects work.
func TestProperty_ParseEmptyObject(t *testing.T) {
	doc, err := Parse([]byte("{}"))
	if err != nil {
		t.Fatalf("Parse error for empty object: %v", err)
	}
	obj := doc.FirstChild()
	if obj == nil || obj.Kind != KindObject {
		t.Fatalf("Expected Object, got %v", obj)
	}
	members := obj.Members()
	if len(members) != 0 {
		t.Fatalf("Expected 0 members, got %d", len(members))
	}
}

// propParseVariousWhitespace asserts various whitespace formats work.
func TestProperty_ParseVariousWhitespace(t *testing.T) {
	inputs := []string{
		"[1]",
		"  [1]",
		"[1]  ",
		"\n\t[1]\r\n",
		"  \n  [1]  \t  ",
		"[  1  ]",
	}
	for _, input := range inputs {
		doc, err := Parse([]byte(input))
		if err != nil {
			t.Fatalf("Parse error for %q: %v", input, err)
		}
		// Must have an array with element 1
		arr := doc.FirstChild()
		if arr == nil || arr.Kind != KindArray {
			t.Fatalf("Expected Array for %q", input)
		}
	}
}

// propParseUnicodeStrings asserts strings with Unicode are preserved.
func TestProperty_ParseUnicodeStrings(t *testing.T) {
	src := `["hello αβγ world 🚀"]`
	doc, err := Parse([]byte(src))
	if err != nil {
		t.Fatalf("Parse error for unicode string: %v", err)
	}
	strs := doc.FindAll(KindString)
	if len(strs) == 0 {
		t.Fatal("No String nodes found")
	}
	for _, s := range strs {
		if s.Value == "" {
			continue
		}
		// Verify the value is well-formed
		if !utf8.ValidString(s.Value) {
			t.Fatalf("String value contains invalid UTF-8: %q", s.Value)
		}
	}
}

// propParseEscapeSequences asserts common escape sequences work.
func TestProperty_ParseEscapeSequences(t *testing.T) {
	tests := []string{
		`["hello\nworld"]`,                   // newline escape
		`["hello\tworld"]`,                   // tab escape
		`["hello\"world"]`,                   // quote escape
		`["hello\\world"]`,                   // backslash escape
		`["hello\/world"]`,                   // slash escape
		`["hello\bworld"]`,                   // backspace
		`["hello\fworld"]`,                   // form feed
		`["hello\rworld"]`,                   // carriage return
		`["\u0048\u0065\u006C\u006C\u006F"]`, // unicode escapes: "Hello"
		`["\u00E9"]`,                         // é
		`["\u2603"]`,                         // ☃ snowman
		`["\u0000"]`,                         // null byte
	}
	for _, src := range tests {
		t.Run("", func(t *testing.T) {
			doc, err := Parse([]byte(src))
			if err != nil {
				t.Fatalf("Parse error for %q: %v", src, err)
			}
			strs := doc.FindAll(KindString)
			if len(strs) == 0 {
				t.Fatalf("No String nodes for %q", src)
			}
		})
	}
}

