// propParseLargeNesting asserts deeply nested structures handle recursion well.
func TestProperty_ParseLargeNesting(t *testing.T) {
	// Build a deeply nested array: [[[[...]]]]
	var sb strings.Builder
	depth := 50
	for i := 0; i < depth; i++ {
		sb.WriteString("[")
	}
	sb.WriteString("1")
	for i := 0; i < depth; i++ {
		sb.WriteString("]")
	}
	src := sb.String()
	doc, err := Parse([]byte(src))
	if err != nil {
		t.Fatalf("Parse error for deep nesting: %v", err)
	}
	// Walk to verify depth
	current := doc
	actualDepth := 0
	for _, c := range current.Children {
		if c.Kind == KindArray {
			_ = c
			actualDepth++
		}
	}
	// We may not get full depth if we don't recurse enough, but shouldn't crash
	_ = actualDepth
}

// propParseComplexGeneratedJSON asserts the generator itself is valid.
func TestProperty_ParseComplexGeneratedJSON(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		// Generate multiple times and combine
		var parts []string
		n := rapid.IntRange(0, 3).Draw(t, "n")
		for i := 0; i < n; i++ {
			parts = append(parts, genFullJSONC(t))
		}
		// Wrap as an array to make it valid (multiple top-level values aren't valid JSON)
		src := "[" + strings.Join(parts, ",") + "]"
		doc, err := Parse([]byte(src))
		if err != nil {
			t.Fatalf("Parse error for combined JSONC: %v\ninput: %q", err, src)
		}
		if doc == nil {
			t.Fatal("Nil document returned")
		}
	})
}

// ============================================================================
// HELPER: Semantic deep compare (ignores trivia)
// ============================================================================

// semanticDeepEqual compares two CST trees ignoring whitespace and comment nodes.
// Returns true if they have the same value structure.
func semanticDeepEqual(a, b *Node) bool {
	if a == nil && b == nil {
		return true
	}
	if a == nil || b == nil {
		return false
	}

	// For leaf value nodes: compare kind and value
	if !a.IsContainer() && !b.IsContainer() {
		if a.IsTrivia() && b.IsTrivia() {
			return true // ignore trivia
		}
		if a.IsTrivia() || b.IsTrivia() {
			return false
		}
		return a.Kind == b.Kind && a.Value == b.Value
	}

	// Container nodes: filter trivia, compare children pairwise
	aKids := filterNonTriviaCST(a.Children)
	bKids := filterNonTriviaCST(b.Children)

	if len(aKids) != len(bKids) {
		return false
	}
	if a.Kind != b.Kind {
		return false
	}
	for i := range aKids {
		if !semanticDeepEqual(aKids[i], bKids[i]) {
			return false
		}
	}
	return true
}

