// propErrorNodeForInvalid asserts that invalid JSON creates error nodes.
func TestProperty_ErrorNodeForInvalid(t *testing.T) {
	tests := []struct {
		input string
		msg   string
	}{
		{`{"a": 01}`, "leading zero in number"},
		{`{"a": true false}`, "extra tokens"},
		{`{`, "unterminated"},
		{`[1,`, "unterminated array"},
	}
	for _, tc := range tests {
		t.Run(tc.msg, func(t *testing.T) {
			doc, err := Parse([]byte(tc.input))
			if err == nil {
				// Should have error nodes
				errs := doc.FindAll(KindError)
				if len(errs) == 0 {
					t.Logf("No error nodes for %q (may still be valid parse strategy)", tc.input)
				}
			}
		})
	}
}

// TestPropertyIntegrity runs a rapid check over all integration-level properties.
func TestProperty_MustRoundTrip(t *testing.T) {
	rapid.Check(t, func(t *rapid.T) {
		input := genFullJSONC(t)
		doc, err := Parse([]byte(input))
		if err != nil {
			return // skip inputs that genuinely can't parse
		}
		// Round-trip through serialize
		serialized := Serialize(doc)
		doc2, err2 := Parse([]byte(serialized))
		if err2 != nil {
			t.Fatalf("Round-trip broke: %v\ninput: %q\nserialized: %q", err2, input, serialized)
		}
		// Structural equality (including trivia)
		if !doc.DeepEqual(doc2) {
			// Debug: show what's different
			t.Fatalf("Round-trip changed structure\ninput: %q\nserialized: %q", input, serialized)
		}
	})
}

// TestProperty_CanonicalNumberFormat verifies that certain number formats
// parse and re-serialize consistently.
func TestProperty_CanonicalNumberFormat(t *testing.T) {
	tests := []string{
		`[0]`,
		`[-0]`,
		`[1]`,
		`[-1]`,
		`[1.5]`,
		`[1.0]`,  // explicit .0
		`[-2.0]`, // negative with .0
		`[1e10]`,
		`[1E10]`, // uppercase E
		`[1e+5]`, // explicit + in exponent
		`[1e-3]`,
		`[1.5e-3]`,
		`[1.2345678901234567e+308]`,
	}
	for _, src := range tests {
		t.Run(src, func(t *testing.T) {
			doc, err := Parse([]byte(src))
			if err != nil {
				t.Fatalf("Parse error for %q: %v", src, err)
			}
			nums := doc.FindAll(KindNumber)
			if len(nums) == 0 {
				t.Fatalf("No number nodes for %q", src)
			}
		})
	}
}

